@page "/catalog"
@using sv_b15688710b794704905d0ec08dad0f12.Components.Catalog
@rendermode InteractiveServer
@inject IProductService ProductService

<PageTitle>Product Catalog</PageTitle>

<h3 class="mb-3">Product Catalog</h3>

@if (_error is not null)
{
    <div class="alert alert-danger" role="alert">
        <strong>Error:</strong> @_error
        <button class="btn btn-sm btn-outline-danger ms-2" @onclick="LoadAsync">Retry</button>
    </div>
}
else
{
    <div class="row g-3">
        <div class="col-md-3">
            <CatalogFilters Categories="_categories"
                            OnFiltersApplied="HandleFiltersApplied"
                            OnFiltersCleared="HandleFiltersCleared" />
        </div>

        <div class="col-md-9">
            @if (_loading)
            {
                <div class="text-center py-5">
                    <div class="spinner-border text-primary" role="status">
                        <span class="visually-hidden">Loading...</span>
                    </div>
                    <p class="mt-2 text-muted">Loading products...</p>
                </div>
            }
            else if (_result is not null)
            {
                <CatalogToolbar SortBy="@_sortBy"
                                FirstItem="FirstItem"
                                LastItem="LastItem"
                                TotalCount="_result.TotalCount"
                                OnSortChanged="HandleSortChanged" />

                @if (_result.Items.Count == 0)
                {
                    <div class="text-center py-5">
                        <p class="text-muted fs-5">No products match your filters.</p>
                        <button class="btn btn-outline-primary" @onclick="HandleFiltersCleared">Clear Filters</button>
                    </div>
                }
                else
                {
                    <div class="row row-cols-1 row-cols-sm-2 row-cols-lg-3 g-3">
                        @foreach (var product in _result.Items)
                        {
                            <div class="col">
                                <ProductCard Product="product"
                                             OnSelected="@(() => HandleProductSelected(product))"
                                             OnAddToCart="@(() => HandleAddToCart(product))" />
                            </div>
                        }
                    </div>

                    <CatalogPagination CurrentPage="_currentPage"
                                       TotalPages="TotalPages"
                                       OnPageChanged="HandlePageChanged" />
                }
            }
        </div>
    </div>
}

@code {
    private List<string>? _categories;
    private PagedResult<Product>? _result;
    private ProductFilter _filter = new(null, null, null, false);
    private string _sortBy = "price_asc";
    private int _currentPage = 1;
    private const int PageSize = 12;
    private bool _loading = true;
    private string? _error;

    private int TotalPages => _result is null || _result.TotalCount == 0
        ? 1
        : (int)Math.Ceiling((double)_result.TotalCount / _result.PageSize);

    private int FirstItem => _result is null || _result.TotalCount == 0
        ? 0
        : (_result.Page - 1) * _result.PageSize + 1;

    private int LastItem => _result is null || _result.TotalCount == 0
        ? 0
        : Math.Min(_result.Page * _result.PageSize, _result.TotalCount);

    [Parameter]
    public EventCallback<Product> OnProductSelected { get; set; }

    protected override async Task OnInitializedAsync()
    {
        await LoadAsync();
    }

    private async Task LoadAsync()
    {
        _loading = true;
        _error = null;

        try
        {
            var categoriesTask = _categories is null
                ? ProductService.GetCategoriesAsync()
                : Task.FromResult(_categories);

            var productsTask = ProductService.SearchAsync(_filter, _sortBy, _currentPage, PageSize);

            await Task.WhenAll(categoriesTask, productsTask);

            _categories = await categoriesTask;
            _result = await productsTask;
        }
        catch (Exception ex)
        {
            _error = ex.Message;
        }
        finally
        {
            _loading = false;
        }
    }

    private async Task HandleFiltersApplied(ProductFilter filter)
    {
        _filter = filter;
        _currentPage = 1;
        await LoadAsync();
    }

    private async Task HandleFiltersCleared()
    {
        _filter = new ProductFilter(null, null, null, false);
        _currentPage = 1;
        await LoadAsync();
    }

    private async Task HandleSortChanged(string sortBy)
    {
        _sortBy = sortBy;
        _currentPage = 1;
        await LoadAsync();
    }

    private async Task HandlePageChanged(int page)
    {
        _currentPage = page;
        await LoadAsync();
    }

    private async Task HandleProductSelected(Product product)
    {
        await OnProductSelected.InvokeAsync(product);
    }

    private Task HandleAddToCart(Product product)
    {
        // Placeholder for add-to-cart logic
        return Task.CompletedTask;
    }
}

